import{z as n,x as i,o as B,c as d,q as r,j as t,D as e,d as a,s as o,S as s,b as A}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"评测组合的策略","description":"","frontmatter":{"title":"评测组合的策略","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ef-eval-portfolio.md","filePath":"llm/ef-eval-portfolio.md","lastUpdated":1791063341000}'),m={name:"llm/ef-eval-portfolio.md"};function p(D,E,C,F,f,h){const l=i("Mermaid");return B(),d("div",null,[E[2]||(E[2]=r('<h1 id="评测组合的策略" tabindex="-1">评测组合的策略 <a class="header-anchor" href="#评测组合的策略" aria-label="Permalink to &quot;评测组合的策略&quot;">​</a></h1><div class="epigraph"><p>评测组合像投资组合：每张卷子有成本、延迟与信噪，目标是覆盖全部声明，而不是把任何一个分数推到最高。</p><footer>—— 据 HELM 多场景口径与 lm-evaluation-harness 实践，按本课程各课协议整理</footer></div><p><a href="/llm/ef-private-eval-build">上一课</a>建成了自家的烟雾集、回归集与盲库。本课把它们与公开卷、动态卷、人评、法官、环境化任务装配成一个<strong>组合</strong>：分层、预算、去冗余、再平衡。零件都在：<a href="/llm/in-training-eval">训练中评测</a>管高频探针，<a href="/llm/agent-eval-protocol">智能体协议</a>管环境化任务，<a href="/llm/live-benchmarks">动态基准</a>管换血，<a href="/llm/human-vs-auto-eval">人机分工</a>管谁该上人。缺口是组合层面的决策：哪张卷降频、哪张卷退役、预算往哪加——单张卷的优化回答不了。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>没有组合观的团队有两种典型病。<strong>肥胖病</strong>：历史上引入的每张卷都全量跑到底，评测税吃掉两位数比例的算力，但没有一张卷因为「不再携带信息」而退役。<strong>裸奔病</strong>：门禁只有一张总分卷，构念覆盖与功效账都没算过，模型换代时才发现某个声明从头到尾没有仪器。两种病同根：卷子的进出没有决策规则。<span class="marginnote">「评测税」就是训练之外花在跑卷子上的算力占比，像交税一样是固定支出。例如训练一个模型花 100 卡时、跑全套评测再花 15 卡时，评测税就是 15%。税太高时的正确反应通常不是加机器，而是让不再携带信息的卷子降频或退役。</span>组合策略要给的就是规则——进（哪个空格必须补仪器）、留（哪张卷值得全量）、退（哪张卷降频或退役）。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>分层金字塔</strong>，从下往上：训练中高频探针（分钟级、便宜、会被背题，只作导航不作门禁）→ CI 烟雾（每次提交，抓回归）→ 每夜回归（主门禁的日常形态）→ 发布门禁（全量 + 盲库 + 人评或标定法官抽审）→ 低频外部对表（公开卷与文献坐标，季度级）。<strong>预算按功效分配</strong>：每层每指标先过<a href="/llm/ef-statistical-power">功效分析</a>，算力加给「区间还压不住目标差」的仪器，而不是加给已经饱和的卷。<strong>去冗余靠相关性</strong>：两张卷在同一批模型上的名次相关 0.95 以上，只留一把主尺全量，另一把降频对表；判别标准不是相关性本身，而是「抽掉这张卷后，有没有哪个声明失去仪器」。<strong>保留异质尺</strong>：程序判、标定法官、人评、环境化任务至少各留一把——它们失效的模式不同，同时失灵的概率小。<span class="marginnote">为什么四类尺各留一把：它们坏的方式不同。程序判在任务被钻空子时失灵，法官随提示风格漂移，人评会累会走神，环境化任务会因环境库过期而失效。四把尺同时坏掉的概率远小于任何一把单独坏掉——「异质」本身就是可靠性。</span></p>',7)),(B(),t(s,null,{default:e(()=>[o(l,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20P1%5B%22%E8%AE%AD%E7%BB%83%E4%B8%AD%E6%8E%A2%E9%92%88%EF%BC%9A%E5%AF%BC%E8%88%AA%22%5D%20--%3E%20P2%5B%22CI%20%E7%83%9F%E9%9B%BE%EF%BC%9A%E6%8A%93%E5%9B%9E%E5%BD%92%22%5D%0A%20%20P2%20--%3E%20P3%5B%22%E6%AF%8F%E5%A4%9C%E5%9B%9E%E5%BD%92%EF%BC%9A%E6%97%A5%E5%B8%B8%E9%97%A8%E7%A6%81%22%5D%0A%20%20P3%20--%3E%20P4%5B%22%E5%8F%91%E5%B8%83%E9%97%A8%E7%A6%81%EF%BC%9A%E5%85%A8%E9%87%8F%20%2B%20%E7%9B%B2%E5%BA%93%20%2B%20%E4%BA%BA%E5%AE%A1%22%5D%0A%20%20P4%20--%3E%20P5%5B%22%E5%A4%96%E9%83%A8%E5%AF%B9%E8%A1%A8%EF%BC%9A%E5%AD%A3%E5%BA%A6%E7%BA%A7%22%5D%0A%20%20BUD%5B%22%E5%8A%9F%E6%95%88%E8%B4%A6%EF%BC%9A%E5%8C%BA%E9%97%B4%E5%8E%8B%E4%B8%8D%E4%BD%8F%E7%9B%AE%E6%A0%87%E7%9A%84%E5%85%88%E5%8A%A0%22%5D%20-.-%3E%20P3%0A%20%20CORR%5B%22%E7%9B%B8%E5%85%B3%E6%80%A7%E7%9F%A9%E9%98%B5%E5%8E%BB%E5%86%97%E4%BD%99%22%5D%20-.-%3E%20P3%0A%20%20CORR%20-.-%3E%20P5%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[a("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,[a("组合的机制目标不是分数最大化而是"),A("strong",null,"声明空间的最小覆盖"),a("：每个对外声明至少一把合格仪器，每把仪器有明确的 \\(\\delta\\)、区间与失效模式。冗余的机制要辩证看：高相关卷子是免费的稳健性检查（两把尺同时翻车说明协议坏了），不是纯浪费——降频不等于删除。再平衡的机制触发器有三类：模型族换代（轴间相关性重算，上一课的年度体检）、产品分布迁移（私有卷抽样框跟着变）、外部环境变化（公开卷被污染、动态卷题源枯竭）。每类触发器都写进组合的运维日历，而不是靠某次事故想起。")],-1)),(B(),t(s,null,{default:e(()=>[o(l,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q0%7B%22%E8%BF%99%E5%BC%A0%E5%8D%B7%E6%80%8E%E4%B9%88%E5%A4%84%E7%BD%AE%3F%22%7D%20--%3E%20Q1%7B%22%E6%8A%BD%E6%8E%89%E5%AE%83%EF%BC%9Cbr%2F%EF%BC%9E%E6%9C%89%E5%A3%B0%E6%98%8E%E5%A4%B1%E5%8E%BB%E4%BB%AA%E5%99%A8%3F%22%7D%0A%20%20Q1%20--%3E%7C%22%E5%90%A6%22%7C%20Q2%7B%22%E4%B8%8E%E4%B8%BB%E5%B0%BA%E7%9B%B8%E5%85%B3%200.95%20%E4%BB%A5%E4%B8%8A%3F%22%7D%0A%20%20Q1%20--%3E%7C%22%E6%98%AF%22%7C%20Q3%7B%22%E5%8C%BA%E9%97%B4%E5%8E%8B%E5%BE%97%E4%BD%8F%E7%9B%AE%E6%A0%87%E5%B7%AE%3F%22%7D%0A%20%20Q2%20--%3E%7C%22%E6%98%AF%22%7C%20F%5B%22%E9%99%8D%E9%A2%91%3A%20%E5%8F%AA%E4%BD%9C%E5%AF%B9%E8%A1%A8%E4%B8%8E%E7%A8%B3%E5%81%A5%E6%80%A7%E6%A3%80%E6%9F%A5%22%5D%0A%20%20Q2%20--%3E%7C%22%E5%90%A6%22%7C%20H%5B%22%E6%8C%89%E5%BC%82%E8%B4%A8%E5%B0%BA%E4%BF%9D%E7%95%99%22%5D%0A%20%20Q3%20--%3E%7C%22%E5%8E%8B%E5%BE%97%E4%BD%8F%22%7C%20FULL%5B%22%E7%95%99%E5%85%A8%E9%87%8F%22%5D%0A%20%20Q3%20--%3E%7C%22%E5%8E%8B%E4%B8%8D%E4%BD%8F%22%7C%20BUD%5B%22%E5%8A%A0%E9%A2%84%E7%AE%97%E6%88%96%E6%8D%A2%E4%BB%AA%E5%99%A8%22%5D%0A%20%20F%20-.-%3E%7C%22%E8%BD%B4%E8%A7%A3%E8%80%A6%E5%90%8E%E4%BF%A1%E6%81%AF%E6%81%A2%E5%A4%8D%22%7C%20FULL%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">评测税有个经验量级：回归与门禁的总算力若超过训练预算的一成，通常说明卷子该退役而不该加机器。先把「每张卷回答哪个声明」写下来，税单自然瘦身。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>组合不能治愈无效仪器：把失效的法官、背题的公开卷留在一层，只会让分层显得体面。层与层的结果冲突要有裁决规则：烟雾红、门禁绿时按协议处理（通常是环境或解码配置漂移，先查<a href="/llm/eval-variance-seed">评测方差</a>的 \\(\\xi\\)），而不是各层各说各话。组合本身也会被优化：团队知道哪张卷进门禁，压力就会集中到那张卷上——门禁层的构成要定期轮换，这也是再平衡的一部分。<span class="marginnote">初学者容易以为「门禁卷越多越保险」。实际恰恰相反：谁都知道哪张卷卡着发布，优化就会悄悄集中到那张卷上——模型不知不觉在「应试」，卷子慢慢失真。所以门禁构成要定期轮换，道理同密码定期更换：不是它坏了，是被人盯上就会坏。</span>最后，外部榜永远在组合的最外层：可参考、可对表、不进门禁——它的公信力问题（谁维护、谁付钱、换尺史）在引用其数字时一并披露。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>组合规则三件：进（空格补仪器）、留（功效账定预算）、退（去冗余与换血）。</li><li>五层金字塔：探针 → 烟雾 → 回归 → 门禁 → 外部对表；只有门禁层决定发布。</li><li>相关 0.95 以上的卷留一把主尺，其余降频；判退役看声明是否失去仪器。</li><li>至少保留四类异质尺：程序判、标定法官、人评、环境化任务。</li><li>出处：据 HELM 多场景口径与 lm-evaluation-harness 实践，按本课程各课协议整理。</li></ul>',5))])}const g=n(m,[["render",p]]);export{c as __pageData,g as default};
